function analyticsId() {
  try {
    const existing = localStorage.getItem('tc_analytics_id');
    if (existing) return existing;
    const next = globalThis.crypto?.randomUUID?.() ?? `tc_${Date.now()}_${Math.random().toString(36).slice(2)}`;
    localStorage.setItem('tc_analytics_id', next);
    return next;
  } catch {
    return `tc_session_${Date.now()}_${Math.random().toString(36).slice(2)}`;
  }
}

function track(event:string, properties:Record<string, string | number | boolean | undefined> = {}) {
  void api.post('/api/analytics', { eventId:crypto.randomUUID(), event, distinctId:analyticsId(), properties }).catch(() => undefined);
}

app.to:
function analyticsId() {
  try {
    const existing = sessionStorage.getItem('tc_technical_session');
    if (existing) return existing;
    const next = crypto.randomUUID();
    sessionStorage.setItem('tc_technical_session', next);
    return next;
  } catch { return 'tc_session_' + crypto.randomUUID(); }
}
function track(event:string, properties:Record<string, string | number | boolean | undefined> = {}) {
  if (localStorage.getItem('tc_analytics_consent') !== 'yes') return;
  void api.post('/api/analytics', { eventId:crypto.randomUUID(), event, distinctId:analyticsId(), properties, consent:true }).catch(() => undefined);
}
function publicDate(item:Listing) {
  if (item.origin === 'direct' || item.date === 'Publicado hoy') return shortDate(item.firstPublishedAt || item.createdAt) || 'Fecha no informada';
  return shortDate(item.sourcePublishedAt || '') || item.date || 'Fecha no informada';
}

